using LinguaPath.Domain.Entities;
using LinguaPath.Shared;

namespace LinguaPath.Infrastructure.Persistence.Seed;

/// <summary>
/// Development-only questions for the sample Spanish course, so the daily quiz, a month 1 exam and the placement test
/// can be tried straight away. Real questions are written in the admin panel (or generated by AI in Phase 5).
/// </summary>
internal static class SampleQuestions
{
    public static List<Question> ForCourse(Course course, IReadOnlyList<Lecture> lectures)
    {
        var list = new List<Question>();
        var allWords = lectures.SelectMany(l => l.Vocabulary).Select(v => v.Meaning).Distinct().ToList();
        var fillers = new[] { "thank you", "please", "water", "house", "good night", "tomorrow" };

        foreach (var lecture in lectures)
        {
            foreach (var word in lecture.Vocabulary.OrderBy(v => v.SortOrder))
            {
                var distractors = allWords.Where(m => m != word.Meaning).Concat(fillers).Distinct().Take(3).ToList();
                list.Add(Q(course, lecture, QuestionType.MultipleChoice, Skill.Vocabulary, 1,
                    $"What does \"{word.Word}\" mean?", null, $"\"{word.Word}\" means \"{word.Meaning}\".",
                    [(word.Meaning, true), .. distractors.Select(d => (d, false))]));
                list.Add(Q(course, lecture, QuestionType.ListenChoose, Skill.Listening, 2,
                    "Which word do you hear?", word.Word, null,
                    [(word.Word, true), .. lecture.Vocabulary.Where(v => v != word).Select(v => (v.Word, false)).Take(2), ("gracias", false)]));
            }

            var example = lecture.Examples.OrderBy(e => e.SortOrder).FirstOrDefault();
            if (example is not null && !string.IsNullOrWhiteSpace(example.Translation))
            {
                list.Add(Q(course, lecture, QuestionType.Translate, Skill.Reading, 2,
                    "Translate into English.", example.TargetText, null, [(example.Translation!, true)]));
                list.Add(Q(course, lecture, QuestionType.ReorderWords, Skill.Grammar, 2,
                    $"Put the words in order: \"{example.Translation}\"", null, null, [(example.TargetText, true)]));
                list.Add(Q(course, lecture, QuestionType.TrueFalse, Skill.Reading, 1,
                    $"\"{example.TargetText}\" means \"{example.Translation}\".", null, null, [("True", true), ("False", false)]));
            }
        }

        // A matching question and a fill-in for the greetings lecture.
        var greetings = lectures.FirstOrDefault(l => l.Title == "Greetings and goodbyes");
        if (greetings is not null)
        {
            list.Add(Q(course, greetings, QuestionType.MatchPairs, Skill.Vocabulary, 2, "Match the Spanish with the English.", null, null,
                [("hola", true, "hello"), ("adiós", true, "goodbye"), ("buenos días", true, "good morning"), ("hasta luego", true, "see you later")]));
            list.Add(Q(course, greetings, QuestionType.FillBlank, Skill.Vocabulary, 2, "Buenos ___, señora. (Good morning)", null,
                "Use \"días\" in the morning, \"tardes\" in the afternoon.", [("días", true), ("dias", true)]));
            list.Add(Q(course, greetings, QuestionType.Writing, Skill.Writing, 3,
                "Write 3–4 sentences introducing yourself in Spanish: your name, where you are from and how you greet a friend.", null, null,
                Array.Empty<(string, bool)>(), points: 5));
            list.Add(Q(course, greetings, QuestionType.Speak, Skill.Speaking, 2, "Say this greeting aloud.", "Buenos días, ¿qué tal?", null,
                Array.Empty<(string, bool)>(), points: 3));
        }

        var ser = lectures.FirstOrDefault(l => l.Title == "Ser: I am, you are");
        if (ser is not null)
        {
            list.Add(Q(course, ser, QuestionType.MultipleChoice, Skill.Grammar, 2, "Nosotros ___ amigos.", null,
                "Ser with nosotros is \"somos\".", [("somos", true), ("son", false), ("sois", false), ("es", false)]));
            list.Add(Q(course, ser, QuestionType.FillBlank, Skill.Grammar, 2, "Tú ___ de México. (ser)", null, "Ser with tú is \"eres\".", [("eres", true)]));
        }

        return list;
    }

    /// <summary>Language-level questions across CEFR levels for the placement test (FR-L11).</summary>
    public static List<Question> Placement(int languageId) =>
    [
        G(languageId, CefrLevel.A1, Skill.Vocabulary, "\"Gracias\" means…", [("thank you", true), ("please", false), ("sorry", false)]),
        G(languageId, CefrLevel.A1, Skill.Grammar, "Yo ___ estudiante.", [("soy", true), ("eres", false), ("es", false)]),
        G(languageId, CefrLevel.A1, Skill.Vocabulary, "Which one is a colour?", [("rojo", true), ("perro", false), ("mesa", false)]),
        G(languageId, CefrLevel.A2, Skill.Grammar, "Ayer yo ___ paella. (comer)", [("comí", true), ("como", false), ("comeré", false)]),
        G(languageId, CefrLevel.A2, Skill.Grammar, "¿Dónde ___ el banco? (location)", [("está", true), ("es", false), ("hay", false)]),
        G(languageId, CefrLevel.A2, Skill.Vocabulary, "\"La semana que viene\" means…", [("next week", true), ("last week", false), ("this weekend", false)]),
        G(languageId, CefrLevel.B1, Skill.Grammar, "Espero que tú ___ a la fiesta. (venir)", [("vengas", true), ("vienes", false), ("vendrás", false)]),
        G(languageId, CefrLevel.B1, Skill.Grammar, "Cuando era niño, ___ al parque cada día. (ir)", [("iba", true), ("fui", false), ("voy", false)]),
        G(languageId, CefrLevel.B2, Skill.Grammar, "Si ___ más tiempo, viajaría más. (tener)", [("tuviera", true), ("tengo", false), ("tendría", false)]),
        G(languageId, CefrLevel.B2, Skill.Vocabulary, "\"Echar de menos\" means…", [("to miss someone", true), ("to throw away", false), ("to make less", false)]),
        G(languageId, CefrLevel.C1, Skill.Grammar, "Si lo ___ sabido, te lo habría dicho. (haber)", [("hubiera", true), ("habría", false), ("había", false)]),
        G(languageId, CefrLevel.C1, Skill.Vocabulary, "\"No dar abasto\" means…", [("to be overwhelmed", true), ("to give up", false), ("to have enough", false)])
    ];

    /// <summary>A month 1 exam built from the sample questions (FR-A64).</summary>
    public static Quiz MonthOneExam(int courseId, IReadOnlyList<Question> questions) => new()
    {
        CourseId = courseId,
        Type = QuizType.Monthly,
        Title = "Month 1 exam",
        Instructions = "Answer every section. Writing and speaking are graded by a teacher.",
        MonthNo = 1,
        TimeLimitMinutes = 30,
        Status = ContentStatus.Published,
        Sections =
        {
            new QuizSection { Title = "Vocabulary", Skill = Skill.Vocabulary, QuestionCount = 5, SortOrder = 1 },
            new QuizSection { Title = "Grammar", Skill = Skill.Grammar, QuestionCount = 3, SortOrder = 2 },
            new QuizSection { Title = "Reading", Skill = Skill.Reading, QuestionCount = 2, SortOrder = 3 },
            new QuizSection { Title = "Listening", Skill = Skill.Listening, QuestionCount = 2, SortOrder = 4 },
            Fixed("Writing", 5, questions.FirstOrDefault(q => q.Type == QuestionType.Writing)),
            Fixed("Speaking", 6, questions.FirstOrDefault(q => q.Type == QuestionType.Speak))
        }
    };

    private static QuizSection Fixed(string title, int order, Question? q)
    {
        var section = new QuizSection { Title = title, SelectionMode = SelectionMode.Fixed, QuestionCount = 1, SortOrder = order };
        if (q is not null) section.Questions.Add(new QuizQuestion { Question = q, SortOrder = 1 });
        return section;
    }

    private static Question Q(Course course, Lecture lecture, QuestionType type, Skill skill, int difficulty, string stem, string? prompt,
        string? explanation, IEnumerable<(string Text, bool Correct)> options, int points = 1) =>
        Q(course, lecture, type, skill, difficulty, stem, prompt, explanation, options.Select(o => (o.Text, o.Correct, (string?)null)), points);

    private static Question Q(Course course, Lecture lecture, QuestionType type, Skill skill, int difficulty, string stem, string? prompt,
        string? explanation, IEnumerable<(string Text, bool Correct, string? Match)> options, int points = 1)
    {
        var q = new Question
        {
            LanguageId = course.LanguageId, CourseId = course.Id, ModuleId = lecture.ModuleId, LectureId = lecture.Id,
            Type = type, Skill = skill, Level = lecture.Level, Difficulty = difficulty, Points = points,
            Stem = stem, Prompt = prompt, Explanation = explanation,
            Status = ContentStatus.Published, Source = ContentSource.Manual
        };
        var order = 0;
        foreach (var (text, correct, match) in options)
            q.Options.Add(new QuestionOption { Text = text, IsCorrect = correct, MatchKey = match, SortOrder = ++order });
        return q;
    }

    private static Question G(int languageId, CefrLevel level, Skill skill, string stem, (string Text, bool Correct)[] options)
    {
        var q = new Question
        {
            LanguageId = languageId, Type = QuestionType.MultipleChoice, Skill = skill, Level = level, Difficulty = (int)level,
            Stem = stem, Status = ContentStatus.Published, Source = ContentSource.Manual
        };
        for (var i = 0; i < options.Length; i++)
            q.Options.Add(new QuestionOption { Text = options[i].Text, IsCorrect = options[i].Correct, SortOrder = i + 1 });
        return q;
    }
}
